(()=>{(Drupal=>{Drupal.behaviors.helsinkiNearYouHtmxFocus={attach(e){if(e!==document){return}const t=e.querySelector(".hdbt-search__results__title--ghost-title");if(t){t.focus({preventScroll:true});t.scrollIntoView({behavior:"smooth",block:"center"})}document.addEventListener("htmx:afterSwap",()=>{const e=new URL(window.location.href).searchParams.has("page");const t=document.querySelector(".hdbt-search__results .card__link");if(e&&t){t.focus({preventScroll:true})}else{const e=document.querySelector(".hdbt-search__results__title");if(e){e.setAttribute("tabindex","-1");e.focus({preventScroll:true})}}},{once:true})}}})(Drupal)})();